import{_ as a,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"64. Pipes and Redirection","description":"The Little Book of C — 64. Pipes and Redirection","frontmatter":{"title":"64. Pipes and Redirection","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 64. Pipes and Redirection","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":64,"sidebarWeight":64,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/064-Pipes and Redirection","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/064-Pipes and Redirection"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/064-Pipes and Redirection.md","filePath":"posts/c教程/en-US/07-Working Close to the System/064-Pipes and Redirection.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/07-Working Close to the System/064-Pipes and Redirection.md"};function t(l,s,o,c,d,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/064-Pipes and Redirection)</p><p>Now that you can read and write with file descriptors, you can connect two processes so that one’s output becomes the other’s input, just like<code>ls | grep c</code> in a shell.</p><p>This magic happens through pipes, one of Unix’s simplest and most elegant inter-process communication (IPC) mechanisms.</p><h4 id="step-1-what-is-a-pipe" tabindex="-1">Step 1. What Is a Pipe? <a class="header-anchor" href="#step-1-what-is-a-pipe" aria-label="Permalink to &quot;Step 1. What Is a Pipe?&quot;">​</a></h4><p>A pipe is a unidirectional data channel between two file descriptors, one for reading, one for writing.</p><p>In the shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls | grep main</span></span></code></pre></div><p>is equivalent to:</p><ul><li>Process A (<code>ls</code>) writes into the pipe.</li><li>Process B (<code>grep</code>) reads from the pipe.</li></ul><p>In C, you can do the same thing using<code>pipe()</code> and<code>fork()</code>.</p><h4 id="step-2-creating-a-pipe" tabindex="-1">Step 2. Creating a Pipe <a class="header-anchor" href="#step-2-creating-a-pipe" aria-label="Permalink to &quot;Step 2. Creating a Pipe&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fds[2];</span></span>
<span class="line"><span>    if (pipe(fds) == -1) {</span></span>
<span class="line"><span>        perror(&quot;pipe failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Read end: %d, Write end: %d\\n&quot;, fds[0], fds[1]);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc pipe_demo.c -o pipe_demo</span></span>
<span class="line"><span>./pipe_demo</span></span></code></pre></div><p>Output example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read end: 3, Write end: 4</span></span></code></pre></div><p>You now have two connected file descriptors:</p><ul><li><code>fds[0]</code>: read end</li><li><code>fds[1]</code>: write end</li></ul><p>Whatever you write into<code>fds[1]</code> can be read from<code>fds[0]</code>.</p><h4 id="step-3-writing-and-reading-through-a-pipe" tabindex="-1">Step 3. Writing and Reading Through a Pipe <a class="header-anchor" href="#step-3-writing-and-reading-through-a-pipe" aria-label="Permalink to &quot;Step 3. Writing and Reading Through a Pipe&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fds[2];</span></span>
<span class="line"><span>    pipe(fds);</span></span>
<span class="line"><span>    const char msg[] = &quot;hello through pipe&quot;;</span></span>
<span class="line"><span>    write(fds[1], msg, strlen(msg));</span></span>
<span class="line"><span>    char buf[64];</span></span>
<span class="line"><span>    ssize_t n = read(fds[0], buf, sizeof(buf) - 1);</span></span>
<span class="line"><span>    buf[n] = &#39;\\0&#39;;</span></span>
<span class="line"><span>    printf(&quot;Received: %s\\n&quot;, buf);</span></span>
<span class="line"><span>    close(fds[0]);</span></span>
<span class="line"><span>    close(fds[1]);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Received: hello through pipe</span></span></code></pre></div><p>You’ve just communicated through memory between two file descriptors, no files, no network.</p><h4 id="step-4-pipes-between-parent-and-child" tabindex="-1">Step 4. Pipes Between Parent and Child <a class="header-anchor" href="#step-4-pipes-between-parent-and-child" aria-label="Permalink to &quot;Step 4. Pipes Between Parent and Child&quot;">​</a></h4><p>Here’s where it gets powerful: pipes can connect processes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fds[2];</span></span>
<span class="line"><span>    pipe(fds);</span></span>
<span class="line"><span>    pid_t pid = fork();</span></span>
<span class="line"><span>    if (pid == 0) {</span></span>
<span class="line"><span>        // Child</span></span>
<span class="line"><span>        close(fds[1]); // close write end</span></span>
<span class="line"><span>        char buf[64];</span></span>
<span class="line"><span>        ssize_t n = read(fds[0], buf, sizeof(buf) - 1);</span></span>
<span class="line"><span>        buf[n] = &#39;\\0&#39;;</span></span>
<span class="line"><span>        printf(&quot;Child got: %s\\n&quot;, buf);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        // Parent</span></span>
<span class="line"><span>        close(fds[0]); // close read end</span></span>
<span class="line"><span>        const char msg[] = &quot;Hi from parent!&quot;;</span></span>
<span class="line"><span>        write(fds[1], msg, strlen(msg));</span></span>
<span class="line"><span>        close(fds[1]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Child got: Hi from parent!</span></span></code></pre></div><p>Parent writes, child reads, a clean data channel between two processes.</p><h4 id="step-5-redirecting-stdin-stdout-to-a-pipe" tabindex="-1">Step 5. Redirecting STDIN/STDOUT to a Pipe <a class="header-anchor" href="#step-5-redirecting-stdin-stdout-to-a-pipe" aria-label="Permalink to &quot;Step 5. Redirecting STDIN/STDOUT to a Pipe&quot;">​</a></h4><p>You can use<code>dup2()</code> to connect a pipe directly to standard input/output.</p><p>Example: connect parent’s write end to child’s stdin.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fds[2];</span></span>
<span class="line"><span>    pipe(fds);</span></span>
<span class="line"><span>    pid_t pid = fork();</span></span>
<span class="line"><span>    if (pid == 0) {</span></span>
<span class="line"><span>        dup2(fds[0], STDIN_FILENO);</span></span>
<span class="line"><span>        close(fds[1]);</span></span>
<span class="line"><span>        execlp(&quot;wc&quot;, &quot;wc&quot;, &quot;-w&quot;, NULL);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        close(fds[0]);</span></span>
<span class="line"><span>        write(fds[1], &quot;Hello from parent\\nThis is a pipe test\\n&quot;, 39);</span></span>
<span class="line"><span>        close(fds[1]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6</span></span></code></pre></div><p>Here’s what happens:</p><ul><li>Parent writes data into the pipe.</li><li>Child’s stdin is connected to that pipe.</li><li><code>wc -w</code> counts the words received.</li></ul><p>This is exactly how the shell implements pipelines like<code>echo &quot;hi&quot; | wc -w</code>.</p><h4 id="step-6-chaining-multiple-commands" tabindex="-1">Step 6. Chaining Multiple Commands <a class="header-anchor" href="#step-6-chaining-multiple-commands" aria-label="Permalink to &quot;Step 6. Chaining Multiple Commands&quot;">​</a></h4><p>You can chain multiple commands by creating multiple pipes and connecting them in series.</p><p>Example concept:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat file.txt | grep &quot;error&quot; | wc -l</span></span></code></pre></div><p>Each process reads from the previous pipe and writes to the next, the shell’s fundamental design.</p><p>You can implement the same concept in C by:</p><ol><li>Creating a pipe between each process pair.</li><li>Forking a new process for each command.</li><li>Redirecting its stdin/stdout via<code>dup2()</code>.</li></ol><h4 id="step-7-named-pipes-fifos" tabindex="-1">Step 7. Named Pipes (FIFOs) <a class="header-anchor" href="#step-7-named-pipes-fifos" aria-label="Permalink to &quot;Step 7. Named Pipes (FIFOs)&quot;">​</a></h4><p>Pipes normally exist only between related processes. To share data between unrelated programs, you can use named pipes (FIFOs).</p><p>Create one:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkfifo mypipe</span></span></code></pre></div><p>Then in one terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &gt; mypipe</span></span></code></pre></div><p>And in another:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &lt; mypipe</span></span></code></pre></div><p>Data flows through the named pipe like a file.</p><p>In C:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/stat.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    mkfifo(&quot;mypipe&quot;, 0666);</span></span>
<span class="line"><span>    int fd = open(&quot;mypipe&quot;, O_WRONLY);</span></span>
<span class="line"><span>    write(fd, &quot;Hello FIFO\\n&quot;, 11);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-8-error-handling-and-eof" tabindex="-1">Step 8. Error Handling and EOF <a class="header-anchor" href="#step-8-error-handling-and-eof" aria-label="Permalink to &quot;Step 8. Error Handling and EOF&quot;">​</a></h4><p>If all write ends of a pipe are closed,<code>read()</code> returns<code>0</code>, indicating EOF.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fds[2];</span></span>
<span class="line"><span>pipe(fds);</span></span>
<span class="line"><span>close(fds[1]); // no writers</span></span>
<span class="line"><span>char buf[10];</span></span>
<span class="line"><span>ssize_t n = read(fds[0], buf, 10); // n == 0 =&gt; EOF</span></span></code></pre></div><p>If you try to write after all readers are gone, you’ll get<code>SIGPIPE</code>.</p><h4 id="tiny-code-minimal-shell-pipeline" tabindex="-1">Tiny Code: Minimal Shell Pipeline <a class="header-anchor" href="#tiny-code-minimal-shell-pipeline" aria-label="Permalink to &quot;Tiny Code: Minimal Shell Pipeline&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/wait.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fds[2];</span></span>
<span class="line"><span>    pipe(fds);</span></span>
<span class="line"><span>    if (fork() == 0) {</span></span>
<span class="line"><span>        dup2(fds[1], STDOUT_FILENO);</span></span>
<span class="line"><span>        close(fds[0]);</span></span>
<span class="line"><span>        execlp(&quot;ls&quot;, &quot;ls&quot;, NULL);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if (fork() == 0) {</span></span>
<span class="line"><span>        dup2(fds[0], STDIN_FILENO);</span></span>
<span class="line"><span>        close(fds[1]);</span></span>
<span class="line"><span>        execlp(&quot;wc&quot;, &quot;wc&quot;, &quot;-l&quot;, NULL);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    close(fds[0]);</span></span>
<span class="line"><span>    close(fds[1]);</span></span>
<span class="line"><span>    wait(NULL);</span></span>
<span class="line"><span>    wait(NULL);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc pipe_chain.c -o pipe_chain</span></span>
<span class="line"><span>./pipe_chain</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(number of files in directory)</span></span></code></pre></div><p>You just recreated<code>ls | wc -l</code> in C.</p><h4 id="step-9-combining-redirection-and-files" tabindex="-1">Step 9. Combining Redirection and Files <a class="header-anchor" href="#step-9-combining-redirection-and-files" aria-label="Permalink to &quot;Step 9. Combining Redirection and Files&quot;">​</a></h4><p>You can redirect stdout or stderr to files the same way:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fd = open(&quot;output.txt&quot;, O_WRONLY | O_CREAT | O_TRUNC, 0644);</span></span>
<span class="line"><span>dup2(fd, STDOUT_FILENO);</span></span>
<span class="line"><span>close(fd);</span></span>
<span class="line"><span>execlp(&quot;ls&quot;, &quot;ls&quot;, NULL);</span></span></code></pre></div><p>Now the output of<code>ls</code> goes to<code>output.txt</code>.</p><h4 id="step-10-why-it-matters" tabindex="-1">Step 10. Why It Matters <a class="header-anchor" href="#step-10-why-it-matters" aria-label="Permalink to &quot;Step 10. Why It Matters&quot;">​</a></h4><p>Pipes and redirection are the heart of Unix philosophy:</p><ul><li>Programs do one thing well.</li><li>Communicate through text streams.</li><li>Compose complex workflows by chaining simple tools.</li></ul><p>Understanding how to implement pipes makes you capable of:</p><ul><li>Building your own shell</li><li>Connecting processes dynamically</li><li>Implementing inter-process communication safely</li></ul><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Recreate<code>ls | grep c</code> using two<code>fork()</code> calls and one pipe.</li><li>Build<code>cat file | wc -l</code>.</li><li>Implement a “tee” program that duplicates output to both stdout and a file.</li><li>Create a named pipe and write to it from one process, read from another.</li><li>Extend your shell to support pipelines of any length.</li></ol><p>Next, you’ll explore how processes signal and interrupt each other, using signals and signal handlers, a crucial concept for handling interrupts, timeouts, and graceful termination.</p>`,80)])])}const g=a(i,[["render",t]]);export{u as __pageData,g as default};
